type Choice = [value: string, text: string, correct: boolean]
function question(code: string, type: LearningQuestionSeed['type'], knowledgeArea: string, difficulty: number,
  learningObjective: string, questionText: string, explanation: string, choices: Choice[]): LearningQuestionSeed {
  return {
    code: `WL001-H10-${code}`, type, knowledgeArea, difficulty, learningObjective, questionText, explanation,
    correctAnswer: choices.filter((choice) => choice[2]).map((choice) => choice[0]),
    options: choices.map(([value, text, isCorrect]) => ({ value, text, isCorrect })),
  }
}

let answerPosition = 0
function single(correct: [string, string], ...wrong: [string, string][]): Choice[] {
  const choices = [...wrong]
  choices.splice(answerPosition++ % (wrong.length + 1), 0, correct)
  return choices.map(([value, text]) => [value, text, value === correct[0]])
}

